"""Coordinate utilities from the dpmodel geometry boundary."""

from __future__ import annotations

import numpy as np


def phys2inter(coord: np.ndarray, cell: np.ndarray) -> np.ndarray:
    return np.matmul(np.asarray(coord), np.linalg.inv(np.asarray(cell)))


def inter2phys(coord: np.ndarray, cell: np.ndarray) -> np.ndarray:
    return np.matmul(np.asarray(coord), np.asarray(cell))


def normalize_coord(coord: np.ndarray, cell: np.ndarray) -> np.ndarray:
    """Wrap physical coordinates into the primitive cell."""
    frac = phys2inter(coord, cell)
    return inter2phys(np.mod(frac, 1.0), cell)


def to_face_distance(cell: np.ndarray) -> np.ndarray:
    """Return distances from the cell origin to the three opposite faces."""
    value = np.asarray(cell, dtype=float).reshape(-1, 3, 3)
    volume = np.linalg.det(value)
    d0 = volume / np.linalg.norm(np.cross(value[:, 1], value[:, 2]), axis=1)
    d1 = volume / np.linalg.norm(np.cross(value[:, 2], value[:, 0]), axis=1)
    d2 = volume / np.linalg.norm(np.cross(value[:, 0], value[:, 1]), axis=1)
    return np.stack([d0, d1, d2], axis=1).reshape(*np.asarray(cell).shape[:-2], 3)

